    private JPanel feedbackPanel(){JTable t=table("Course","Response status","Responses","Average / 5","Latest anonymous comments");refreshFeedback(t);JPanel controls=new JPanel(new FlowLayout(FlowLayout.LEFT));JTextField code=new JTextField(10);controls.add(new JLabel("Course code"));controls.add(code);controls.add(button("View summary",()->{List<String[]> s=service.feedbackSummary(user,code.getText().trim().toUpperCase());List<String[]> rows=new ArrayList<>();if(!s.isEmpty()&&s.get(0)[0].equals("SUPPRESSED"))rows.add(new String[]{code.getText(),"SUPPRESSED",s.get(0)[1],"Hidden until minimum response threshold",""});else{String count=s.get(0)[1],avg=s.get(0)[2];StringBuilder comments=new StringBuilder();for(int i=1;i<s.size();i++)if(!s.get(i)[1].isBlank())comments.append("• ").append(s.get(i)[1]).append("\n");rows.add(new String[]{code.getText(),"VISIBLE",count,avg,comments.toString()});}fill(t,rows);}));controls.add(button("Refresh all courses",()->refreshFeedback(t)));return wrap(t,controls);}
    private void refreshFeedback(JTable t){run(()->{List<String[]> rows=new ArrayList<>();for(CrfmsService.Course c:service.courses(user,"",null,true)){List<String[]> s=service.feedbackSummary(user,c.code);if(!s.isEmpty()){if(s.get(0)[0].equals("SUPPRESSED"))rows.add(new String[]{c.code,"SUPPRESSED",s.get(0)[1],"Hidden",""});else rows.add(new String[]{c.code,"VISIBLE",s.get(0)[1],s.get(0)[2],"Use View summary to inspect comments"});}}fill(t,rows);});}
    private JPanel studentFeedbackPanel(){JTable t=table("Course code","Course title","Rating","Comment");JPanel controls=new JPanel(new FlowLayout(FlowLayout.LEFT));controls.add(button("Submit / edit feedback",()->{String code=requiredAsk("Registered course code","").toUpperCase();int rating=intAsk("Rating (1-5)",4,1,5);String comment=requiredAsk("Comment (can be brief)","");service.saveFeedback(user,code,rating,comment);JOptionPane.showMessageDialog(this,"Feedback saved. Your identity is not shown in faculty reports.");}));controls.add(button("My registered courses",()->{List<String[]> rows=new ArrayList<>();for(String[] r:service.registrations(user))if(r[5].equals("REGISTERED"))rows.add(new String[]{r[2],r[3],"",""});fill(t,rows);}));return wrap(t,controls);}
