    private JPanel periodsPanel(){JTable t=table("ID","Name","Start date","End date","Open","Minimum responses");refreshPeriods(t);JPanel controls=new JPanel(new FlowLayout(FlowLayout.LEFT));controls.add(button("Create period",()->{String name=requiredAsk("Period name","Midterm feedback");String start=requiredAsk("Start date (YYYY-MM-DD)",java.time.LocalDate.now().toString());String end=requiredAsk("End date (YYYY-MM-DD)",java.time.LocalDate.now().plusDays(14).toString());int min=intAsk("Minimum responses",3,1,1000);service.createFeedbackPeriod(user,name,start,end,min);refreshPeriods(t);}));controls.add(button("Open / close selected period",()->{long id=Long.parseLong(selected(t,0));boolean open=selected(t,4).equals("0");service.setFeedbackPeriodOpen(user,id,open);refreshPeriods(t);}));controls.add(button("Refresh",()->refreshPeriods(t)));return wrap(t,controls);}
