    private JPanel studentTeachingFeedbackPanel(){JTable t=table("Feedback periods","Name","Start","End","Open","Min responses");refreshPeriods(t);JPanel controls=new JPanel(new FlowLayout(FlowLayout.LEFT));controls.add(button("Submit teaching feedback",()->{long period=Long.parseLong(requiredAsk("Period ID","").trim());String code=requiredAsk("Registered course code","").toUpperCase();String[] cats={"Clarity","Preparation","Pace","Engagement","Examples","Availability","Fairness","Materials","Feedback quality","Overall"};int[] ratings=new int[10];for(int i=0;i<10;i++){String v=choose(cats[i]+" (0 = skip)",new String[]{"0 - Skip","1","2","3","4","5"});ratings[i]=Integer.parseInt(v.substring(0,1));}String tags=requiredAsk("Tags (comma-separated, up to 5)","");String suggestion=requiredAsk("Optional suggestion (max 300 chars)","");service.submitTeachingFeedback(user,code,period,ratings,tags,suggestion);JOptionPane.showMessageDialog(this,"Teaching feedback saved. Results remain hidden until the response threshold is reached.");}));return wrap(t,controls);}
